<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { useHead } from '@vueuse/head'
import { t } from '@/i18n'
import ChannelList from '@components/ChannelList.vue'
import GroupInviteBanner from '@components/GroupInviteBanner.vue'
import BuildBadge from '@components/BuildBadge.vue'
import PeerList from '@components/PeerList.vue'
import VoiceControls from '@components/VoiceControls.vue'
import AudioVisualizer from '@components/AudioVisualizer.vue'
import ChatPanel from '@components/ChatPanel.vue'

const router = useRouter()
const authStore = useAuthStore()
const voiceStore = useVoiceStore()

useHead({
  title: 'Sprachchat - SimpleVoiceChat',
})

const showChannels = ref(true)
const showPeers = ref(true)
const showVisualizer = ref(false)
const activeTab = ref<'voice' | 'chat'>('voice')

const isNarrow = ref(false)
const isNarrowScreen = () =>
  typeof window !== 'undefined' && window.innerWidth <= 1024

/* On phones/tablets the drawers would cover each other and the content,
   so they start closed and stay mutually exclusive. */
function toggleChannels() {
  showChannels.value = !showChannels.value
  if (showChannels.value && isNarrowScreen()) showPeers.value = false
}

function togglePeers() {
  showPeers.value = !showPeers.value
  if (showPeers.value && isNarrowScreen()) showChannels.value = false
}

/* Tapping next to an open drawer closes it - on phones the footer toggle
   can be out of reach behind the content. */
function closeDrawers() {
  showChannels.value = false
  showPeers.value = false
}

const drawerBackdropVisible = computed(
  () => isNarrow.value && (showChannels.value || showPeers.value),
)

/* If the viewport turns narrow later (resize, rotation, device emulation)
   with both drawers open, keep only the channels drawer. */
let narrowQuery: MediaQueryList | null = null
function syncNarrowState() {
  isNarrow.value = narrowQuery?.matches ?? false
  enforceNarrowExclusivity()
}
function enforceNarrowExclusivity() {
  if (narrowQuery?.matches && showChannels.value && showPeers.value) {
    showPeers.value = false
  }
}

const isConnected = computed(() => voiceStore.state.isConnected)
const isConnecting = computed(() => voiceStore.state.isConnecting)
const currentChannel = computed(() => voiceStore.state.currentChannel)
const peerCount = computed(() => voiceStore.peerCount)
const microphoneWarning = computed(() => voiceStore.state.microphoneWarning)
const connectionNotice = computed(() => voiceStore.connectionNotice)
const serverUnreachable = computed(() => voiceStore.state.serverUnreachable)
const isReconnecting = computed(() => voiceStore.state.isReconnecting)

async function handleRetry() {
  await voiceStore.retryConnection()
}

async function handleDisconnect() {
  await voiceStore.disconnect()
}

async function handleLeaveChannel() {
  await voiceStore.leaveChannel()
}

onMounted(() => {
  if (!authStore.isAuthenticated) {
    router.push('/login')
    return
  }
  voiceStore.restoreSettings()
  narrowQuery = window.matchMedia('(max-width: 1024px)')
  if (narrowQuery.matches) {
    showChannels.value = false
    showPeers.value = false
  }
  syncNarrowState()
  narrowQuery.addEventListener('change', syncNarrowState)
})

onUnmounted(() => {
  voiceStore.persistSettings()
  narrowQuery?.removeEventListener('change', syncNarrowState)
  narrowQuery = null
})
</script>

<template>
  <div class="voice-view">
    <header class="voice-header">
      <div class="header-left">
        <h1>SimpleVoiceChat</h1>
        <BuildBadge />
        <span v-if="currentChannel" class="channel-badge">{{ currentChannel }}</span>
      </div>
      
      <div class="header-center">
        <div
          class="connection-status"
          :class="['status', { connected: isConnected, connecting: isConnecting, lost: serverUnreachable }]"
          role="status"
          aria-live="polite"
        >
          <span class="status-dot" aria-hidden="true"></span>
          <span v-if="serverUnreachable">
            {{ isReconnecting ? t('app.statusRetrying') : t('app.statusLost') }}
          </span>
          <span v-else>{{ isConnecting ? t('app.statusConnecting') : isConnected ? t('app.statusConnected') : t('app.statusDisconnected') }}</span>
        </div>

        <button
          v-if="serverUnreachable"
          class="btn btn-secondary btn-sm"
          :disabled="isReconnecting"
          @click="handleRetry"
        >
          {{ isReconnecting ? t('app.retrying') : t('app.retry') }}
        </button>

        <div v-if="isConnected" class="peer-count">
          <span>{{ t('app.participants', { count: peerCount }) }}</span>
        </div>
      </div>
      
      <div class="header-right">
        <div class="header-toggles" role="group" aria-label="Ansichten">
          <button @click="toggleChannels" class="btn btn-icon" :class="{ active: showChannels }" :aria-label="t('app.toggleChannelsAria')" :aria-pressed="showChannels">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </button>
          <button @click="showVisualizer = !showVisualizer" class="btn btn-icon" :class="{ active: showVisualizer }" :aria-label="t('app.toggleVisualizerAria')" :aria-pressed="showVisualizer">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M4 13a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2H6a2 2 0 01-2-2v-4z" />
              <polyline points="8 17 12 13 16 17" />
              <line x1="12" y1="9" x2="12" y2="17" />
            </svg>
          </button>
          <button @click="togglePeers" class="btn btn-icon" :class="{ active: showPeers }" :aria-label="t('app.togglePeersAria')" :aria-pressed="showPeers">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
              <circle cx="9" cy="7" r="4" />
              <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
              <path d="M16 3.13a4 4 0 0 1 0 7.75" />
            </svg>
          </button>
        </div>
        <button
          v-if="isConnected"
          @click="handleLeaveChannel"
          class="btn btn-secondary"
          :aria-label="t('app.leaveChannel')"
        >
          {{ t('app.leaveChannel') }}
        </button>
        <button
          v-else-if="isConnecting"
          @click="handleDisconnect"
          class="btn btn-secondary"
          :aria-label="t('app.cancelConnect')"
        >
          {{ t('app.cancelConnect') }}
        </button>
        <button @click="$router.push('/settings')" class="btn btn-icon" :aria-label="t('app.settings')">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <circle cx="12" cy="12" r="3" />
            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z" />
          </svg>
        </button>
        <button
          v-if="isConnected"
          @click="handleDisconnect"
          class="btn btn-danger"
          :aria-label="t('app.disconnect')"
        >
          {{ t('app.disconnect') }}
        </button>
      </div>
    </header>

    <div
      v-if="drawerBackdropVisible"
      class="drawer-backdrop"
      aria-hidden="true"
      @click="closeDrawers"
    ></div>

    <nav class="main-tabs" :aria-label="t('app.tabs')">
      <button :class="{ active: activeTab === 'voice' }" @click="activeTab = 'voice'">{{ t('app.tabVoice') }}</button>
      <button :class="{ active: activeTab === 'chat' }" @click="activeTab = 'chat'">{{ t('app.tabChat') }}</button>
    </nav>

    <main class="voice-main">
      <p v-if="connectionNotice" class="connection-notice" role="status">{{ connectionNotice }}</p>
      <GroupInviteBanner />
      <div v-if="activeTab === 'voice'" class="voice-workspace">
      <aside v-show="showChannels" class="sidebar sidebar-channels" :class="{ open: showChannels }">
        <ChannelList @channel-selected="handleLeaveChannel" />
      </aside>
      
      <section class="voice-content">
        <!-- The warning belongs inside the column, .voice-workspace is a row.
             As a direct child it took the full width and pushed the controls out. -->
        <div v-if="microphoneWarning" class="microphone-warning" role="status">
          {{ microphoneWarning }}
        </div>

        <div class="voice-controls-section">
          <VoiceControls />
        </div>
        
        <div class="visualizer-section">
          <AudioVisualizer v-show="showVisualizer" />
        </div>
        
        <aside v-show="showPeers" class="sidebar sidebar-peers" :class="{ open: showPeers }">
          <PeerList />
        </aside>
      </section>
      </div>
      <ChatPanel v-else />
    </main>

    <footer v-if="activeTab === 'voice'" class="voice-footer">
      <div class="footer-toggle">
        <button @click="toggleChannels" class="toggle-btn" :class="{ active: showChannels }" :aria-label="t('app.toggleChannelsAria')">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
          </svg>
          {{ t('app.toggleChannels') }}
        </button>
        <button @click="showVisualizer = !showVisualizer" class="toggle-btn" :class="{ active: showVisualizer }" :aria-label="t('app.toggleVisualizerAria')">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M4 13a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2H6a2 2 0 01-2-2v-4z" />
            <polyline points="8 17 12 13 16 17" />
            <line x1="12" y1="9" x2="12" y2="17" />
          </svg>
          {{ t('app.toggleVisualizer') }}
        </button>
        <button @click="togglePeers" class="toggle-btn" :class="{ active: showPeers }" :aria-label="t('app.togglePeersAria')">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
            <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
            <circle cx="9" cy="7" r="4" />
            <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
            <path d="M16 3.13a4 4 0 0 1 0 7.75" />
          </svg>
          {{ t('app.togglePeers') }}
        </button>
      </div>
    </footer>
  </div>
</template>

<style scoped src="./voice-view.css"></style>
