<script setup lang="ts">
import { computed } from 'vue'
import { useVoiceStore } from '@stores/useVoiceStore'
import { t } from '@/i18n'

const voiceStore = useVoiceStore()

/** Shown while invited to another group; accepting joins (with password). */
const visible = computed(
  () => voiceStore.groupInvite !== null &&
    voiceStore.state.currentChannel !== voiceStore.groupInvite?.groupId,
)
</script>

<template>
  <div v-if="visible && voiceStore.groupInvite" class="group-invite" role="alert">
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true">
      <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2" />
      <circle cx="9" cy="7" r="4" />
      <path d="M23 21v-2a4 4 0 0 0-3-3.87" />
      <path d="M16 3.13a4 4 0 0 1 0 7.75" />
    </svg>
    <p>{{ t('group.inviteText', { from: voiceStore.groupInvite.fromName, name: voiceStore.groupInvite.groupName }) }}</p>
    <div class="group-invite-actions">
      <button type="button" class="btn btn-primary btn-sm" @click="voiceStore.acceptGroupInvite()">
        {{ t('group.join') }}
      </button>
      <button type="button" class="btn btn-secondary btn-sm" @click="voiceStore.dismissGroupInvite()">
        {{ t('group.inviteDismiss') }}
      </button>
    </div>
  </div>
</template>

